CREATE TRIGGER workflow_version_increment
			AFTER UPDATE ON workflow_entity
			FOR EACH ROW
			WHEN OLD."versionCounter" = NEW."versionCounter"
			BEGIN
				UPDATE workflow_entity
				SET "versionCounter" = "versionCounter" + 1
				WHERE id = NEW.id;
			END;
